sp_widget.client_script:
function registrationFormController($scope) {
  var c = this;
  c.data = c.data || {};
  c.submitting = false;
  c.errorMsg = "";
  c.register = function() {
    c.errorMsg = "";
    if (!c.data.fullName || !c.data.email) {
      c.errorMsg = "Please enter your name and email address.";
      return;
    }
    c.submitting = true;
    c.data.action = "register";
    c.server.update().then(function(response) {
      c.submitting = false;
      if (response.data.error) {
        c.errorMsg = response.data.error;
      }
    });
  };
}

sp_widget.script:
(function(data, input) {
	data.submitted = false;
	if (!input || input.action !== "register") { return; }
	var fullName = (input.fullName || "").trim();
	var email = (input.email || "").trim().toLowerCase();
	if (!fullName || !email) { data.error = "Please provide your name and email address."; return; }
	var emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
	if (!emailPattern.test(email)) { data.error = "Please enter a valid email address."; return; }

	var existing = new GlideRecord("sys_user");
	existing.addQuery("email", email);
	existing.query();
	if (existing.next()) { data.error = "An account with this email address already exists."; return; }

	var nameParts = fullName.split(" ");
	var firstName = nameParts.shift();
	var lastName = nameParts.join(" ") || firstName;

	// sys_user create is ACL-restricted to the ai_user_admin role, which the guest
	// portal session never holds. Briefly impersonate the built-in admin account to
	// perform the insert + password-reset trigger, then revert to the original session.
	var ADMIN_SYS_ID = "6816f79cc0a8016401c5a33be04be441";
	var originalUserId = gs.getUserID();
	var newUserSysId = null;
	var impersonated = false;
	try {
		gs.impersonate(ADMIN_SYS_ID);
		impersonated = true;

		var user = new GlideRecord("sys_user");
		user.initialize();
		user.first_name = firstName;
		user.last_name = lastName;
		user.name = fullName;
		user.email = email;
		user.user_name = email;
		user.active = false;
		user.locked_out = true;
		user.password_needs_reset = true;
		newUserSysId = user.insert();

		if (newUserSysId) {
			try {
				var pwdUtil = new global.PasswordResetUtil();
				var requestId = pwdUtil.validateUser(newUserSysId);
				if (requestId) {
					pwdUtil.raiseSendEmailEvent(user, requestId, gs.getProperty("glide.servlet.uri"));
				} else {
					gs.eventQueue("password.reset.url", user, newUserSysId, "");
				}
			} catch (ex) {
				gs.error("Travel Buddy registration: password reset trigger failed - " + ex.message);
			}
		}
	} finally {
		if (impersonated) {
			gs.impersonate(originalUserId);
		}
	}

	if (!newUserSysId) {
		data.error = "We were unable to create your account. Please try again later.";
		return;
	}

	data.submitted = true;
})(data, input);
